// TypeScript test file parser.
//
// Port of Rust implementation from `oxc/tasks/coverage/src/typescript/meta.rs`.
// Generated by GitHub Copilot initially and amended since.
//
// Only the part which splits a test file into units is ported. The Rust version also reads
// TypeScript's `*.errors.txt` baselines, to find the fixtures TypeScript itself expects not to compile,
// and skips them. Nothing here needs that - these tests compare two implementations on the same source,
// and whether TypeScript would reject that source has no bearing on whether the two agree about it.
//
// This file is duplicated in `oxc-project/estree-conformance` repo in `src/utils` directory,
// and in `napi/parser/test` in this repo. Any changes made here should also be replicated there.

import path from "path";

// Regex patterns equivalent to the Rust version
const META_OPTIONS_REGEX = /^\/\/\s*@(\w+)\s*:\s*([^\r\n]*)/gm;

interface SourceType {
  typescript: boolean;
  jsx: boolean;
  module: boolean;
}

interface TestUnitData {
  name: string;
  content: string;
  sourceType: SourceType;
}

interface TestCaseContent {
  tests: TestUnitData[];
}

/**
 * Whether the test file sets a `@jsx` compiler option, which forces JSX on for every unit in it.
 *
 * The only compiler option any of this needs. Values are already trimmed when they go into the map,
 * so an empty string means the directive was there with nothing after it.
 *
 * @param options - Compiler options
 */
function hasJsxOption(options: Map<string, string>): boolean {
  const jsx = options.get("jsx");
  return jsx !== undefined && jsx !== "";
}

// Mapping from file extension to source type
const EXTENSIONS = {
  ".js": { typescript: false, jsx: false, module: true },
  ".mjs": { typescript: false, jsx: false, module: true },
  ".cjs": { typescript: false, jsx: false, module: false },
  ".jsx": { typescript: false, jsx: true, module: true },
  ".ts": { typescript: true, jsx: false, module: true },
  ".mts": { typescript: true, jsx: false, module: true },
  ".cts": { typescript: true, jsx: false, module: false },
  ".tsx": { typescript: true, jsx: true, module: true },
};

function isSupportedExtension(ext: string): ext is keyof typeof EXTENSIONS {
  return Object.hasOwn(EXTENSIONS, ext);
}

/**
 * Check if extension explicitly indicates module type
 * @param ext - File extension (lowercase, with dot)
 */
function isExplicitModuleExtension(ext: string): boolean {
  return [".mts", ".mjs", ".cjs", ".cts"].includes(ext);
}

/**
 * Get source type from file path
 * @param filePath - Path to the file
 * @param jsxOption - `true` if the test file sets a `@jsx` compiler option
 * @returns Source type, or `null` for an unsupported extension
 */
function getSourceType(filePath: string, jsxOption: boolean): SourceType | null {
  const ext = path.extname(filePath).toLowerCase();
  if (!isSupportedExtension(ext)) return null;

  // For explicit module extensions (.mts, .mjs, .cjs, .cts), preserve the extension-based module value.
  // For ambiguous extensions (.js, .jsx, .ts, .tsx), use content-based detection (start with false).
  const sourceType: SourceType = {
    ...EXTENSIONS[ext],
    module: isExplicitModuleExtension(ext) ? EXTENSIONS[ext].module : false,
  };
  if (jsxOption) sourceType.jsx = true;

  return sourceType;
}

/**
 * Extract individual test units from a TypeScript test file
 * @param filePath - Path to the test file
 * @param code - Content of the test file
 * @returns Parsed test case content
 */
export function makeUnitsFromTest(filePath: string, code: string): TestCaseContent {
  const currentFileOptions = new Map<string, string>();
  let currentFilename: string | null = null;
  const testUnitData: Omit<TestUnitData, "sourceType">[] = [];
  let currentFileContent = "";

  // Process the file line by line
  const lines = code.split(/\r?\n/);
  if (lines[lines.length - 1] === "") lines.length--;

  for (const line of lines) {
    // Reset regex state
    META_OPTIONS_REGEX.lastIndex = 0;
    const match = META_OPTIONS_REGEX.exec(line);

    if (match) {
      const metaName = match[1].toLowerCase();
      const metaValue = match[2].trim();

      if (metaName === "filename") {
        if (currentFilename !== null) {
          testUnitData.push({
            name: currentFilename,
            content: currentFileContent,
          });
          currentFileContent = "";
        }
        currentFilename = metaValue;
      } else {
        currentFileOptions.set(metaName, metaValue);
      }
    } else {
      if (currentFileContent.length > 0) {
        currentFileContent += "\n";
      }
      currentFileContent += line;
    }
  }

  // Handle the last file (or the only file if no @filename is used)
  const filename = currentFilename || path.basename(filePath);
  testUnitData.push({
    name: filename,
    content: currentFileContent,
  });

  const jsxOption = hasJsxOption(currentFileOptions);

  // Update source types and filter out unsupported files
  const isModule = testUnitData.length > 1;
  const validTestUnits: TestUnitData[] = [];
  for (const unit of testUnitData) {
    const sourceType = getSourceType(unit.name, jsxOption);
    if (!sourceType) continue;
    // Only upgrade to module for ambiguous extensions (.ts, .js, .tsx, .jsx).
    // Explicit extensions (.mts, .mjs, .cjs, .cts) should keep their extension-based module kind.
    const ext = path.extname(unit.name).toLowerCase();
    if (isModule && !isExplicitModuleExtension(ext)) sourceType.module = true;
    validTestUnits.push({ ...unit, sourceType });
  }

  return { tests: validTestUnits };
}
